using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() => Type = {personInfo.Type.Name}, " +
                  $"Properties = {personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// 2a – type the resolver *can* handle (default reflection resolver)
if (options.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGetTypeInfo<Person>() => found ({info!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person>() => not available");

// 2b – use a source-gen context that only knows about Person,
//       so querying for int[] will return false instead of throwing.
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<int[]>(out var arrayInfo))
    Console.WriteLine($"TryGetTypeInfo<int[]>() => found ({arrayInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<int[]>() => not available (resolver doesn't know this type)");

// ----- types -----
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class LimitedContext : JsonSerializerContext;

